    el.ouverts.setAttribute('opacity', joie ? 0 : 1);
    if (joie) { el.fermeG.setAttribute('opacity', 0); el.fermeD.setAttribute('opacity', 0); }
    // les pupilles : elles suivent le regard, et rapetissent quand il écarquille les yeux (p.pupille < 1)
    el.pupilles.forEach((x, i) => { const [cx, cy] = i ? [535, 344] : [479, 345]; x.setAttribute('transform', `translate(${p.regardX} ${p.regardY}) translate(${cx} ${cy}) scale(${p.pupille}) translate(${-cx} ${-cy})`); });
