        l.setAttribute('x1', cx + r0 * Math.cos(ang)); l.setAttribute('y1', cy + r0 * Math.sin(ang));
        l.setAttribute('x2', cx + r1 * Math.cos(ang)); l.setAttribute('y2', cy + r1 * Math.sin(ang));
