      teteRot: (ms) => (ms > 2500 ? 0 : -8 * Math.sin(ms / 2500 * 4 * Math.PI - .5)),
      teteX: (ms) => (ms > 2500 ? 0 : -14 * Math.sin(ms / 2500 * 4 * Math.PI - .4)),
      chapY: (ms) => (ms > 2500 ? 0 : 50 * Math.max(0, Math.sin(ms / 2500 * 8 * Math.PI))),
