      bD: (ms) => (ms > 2500 ? P.bD : -22 * Math.sin(ms / 2500 * 8 * Math.PI)),
      mainG: [[0, 'pendante'], [150, 'coucou'], [2500, 'pendante']], mainD: [[0, 'pendante'], [150, 'coucou'], [2500, 'pendante']],
